steps.script:
GameState.state["factions"]["1"]["detachment"] = "Da Big Hunt"
StratagemManager.load_faction_stratagems_for_player(1)
FactionAbilityManager.detect_player_detachment(1)
load("res://scripts/codex/orks/OrkDetachments11e.gd").apply_keyword_grants(1)
SettingsService.set("auto_allocate_wounds", true)
var _ms_U_ALLARUS_CUSTODIANS_A = GameState.state.units["U_ALLARUS_CUSTODIANS_A"].models
for _i in range(_ms_U_ALLARUS_CUSTODIANS_A.size()):
	_ms_U_ALLARUS_CUSTODIANS_A[_i]["position"] = {"x": (30.000000 + (float(_i) - float(_ms_U_ALLARUS_CUSTODIANS_A.size() - 1) / 2.0) * 1.830000) * 40.0, "y": 33.500000 * 40.0}
var _ms_U_CONTEMPTOR_A = GameState.state.units["U_CONTEMPTOR_A"].models
for _i in range(_ms_U_CONTEMPTOR_A.size()):
	_ms_U_CONTEMPTOR_A[_i]["position"] = {"x": (30.000000 + (float(_i) - float(_ms_U_CONTEMPTOR_A.size() - 1) / 2.0) * 1.600000) * 40.0, "y": 22.200000 * 40.0}
GameState.state.players["2"]["cp"] = 0
tree.current_scene._recreate_unit_visuals()
return FactionAbilityManager.get_player_detachment(1)

var tl = tree.root.get_node("AttackAssignmentDialog/Content/TargetList")
var out = []
for i in range(tl.item_count):
	out.append(str(tl.get_item_metadata(i)))
return ",".join(out)

var p = PhaseManager.get_current_phase_instance()
var ctx = []
for d in p.dice_log:
	if typeof(d) == TYPE_DICTIONARY:
		ctx.append([str(d.get("context", "")), str(d.get("weapon", "")), str(d.get("ap", ""))])
print("[O34 big hunt] dice log: ", ctx)
return ctx.size()

var p = PhaseManager.get_current_phase_instance()
var w := ""
var ok := 0
for d in p.dice_log:
	if typeof(d) != TYPE_DICTIONARY:
		continue
	var c := str(d.get("context", ""))
	if c == "hit_roll_melee":
		w = str(d.get("weapon", ""))
	elif "save" in c and d.has("ap") and w != "":
		var base := int(str(RulesEngine.get_weapon_profile(w, GameState.state).get("ap", "0")))
		if int(d.ap) == base - 1:
			ok += 1
return ok
